        Bucket bucket = getBucket(［c］);
        if (offset == 0 && length != 0) {
            bucket.next = new Bucket();
            bucket = bucket.next;
        }
        bucket.data[offset] = c;
        length++;
        return this;
    }

    public String toString() {
        char[] data = new char[length];
        Bucket bucket = bucketList;
        int size;
